mapper.select:
select aw.`staff_id` as `userId`,
count(DISTINCT aw.`date`) as `workDays`
from `arrange_work` aw
where aw.`deleted` = 0 and aw.`arrange_work_classes_ids` is not null and aw.`arrange_work_classes_ids` != ''

    and aw.`staff_id` = #{param.userId}


    and aw.`staff_id` in

        #{id}



    and aw.`date` >= #{param.period.begin}


    and aw.`date` < #{param.period.end}

GROUP by aw.`staff_id`

SELECT aw.`id`, aw.`staff_id`, aw.`staff_name`, aw.`staff_mobile`, aw.`arrange_work_classes_ids`, aw.`month`, aw.`week`, aw.`date`, aw.`group_id`, awc.`id` AS awcId, awc.`classes_id`, awc.`NAME`, awc.`start_work_time`, awc.`end_work_time`, awc.`end_time_is_morrow` FROM `arrange_work` aw LEFT JOIN `arrange_work_classes` awc ON aw.`arrange_work_classes_ids` LIKE CONCAT( '%', awc.`id` , '%' ) WHERE 1 = 1
and aw.`staff_name` like CONCAT('%', #{param.keyword}, '%')
and aw.`group_id` = #{param.groupId}
and aw.month = #{param.month}
and aw.date between #{param.period.begin} and #{param.period.end}
and aw.`staff_organizationId` = #{param.organizationId}
and aw.`staff_id` = #{param.currentUserId}
ORDER BY aw.`date`, date_format(CONCAT(aw.`date`, ' ', awc.`start_work_time` ),'%Y-%m-%d %H:%i')

SELECT aw.`id`, aw.`staff_id`, aw.`staff_name`, aw.`staff_mobile`, aw.`arrange_work_classes_ids`, aw.`month`, aw.`week`, aw.`date`, ag.`name` AS `groupName`, o.`name` AS `deptName`, awc.`id` AS `awcId`, awc.`classes_id`, awc.`NAME`, awc.`start_work_time`, awc.`end_work_time`, awc.`end_time_is_morrow` FROM `arrange_work` aw LEFT JOIN `arrange_work_classes` awc ON aw.`arrange_work_classes_ids` LIKE CONCAT( '%', awc.`id` , '%' ) LEFT JOIN `attendance_group` ag ON aw.`group_id` = ag.`id` LEFT JOIN `cube-biz-ouaa`.`organization` o ON aw.`staff_organization_id` = o.`id` LEFT JOIN `attendance_group_staff` ags ON aw.`staff_id` = ags.`staff_id` and ags.`group_type` = 'ARRANGE' WHERE 1 = 1 AND ag.`name` IS NOT NULL AND ags.`id` IS NOT NULL
and aw.`staff_name` like CONCAT('%', #{param.keyword}, '%')
and aw.`group_id` = #{param.groupId}
and aw.`month` = #{param.month}
and aw.`date` between #{param.period.begin} and #{param.period.end}
and aw.`staff_organizationId` = #{param.organizationId}
ORDER BY aw.`date`, date_format(CONCAT(aw.`date`, ' ', awc.`start_work_time` ),'%Y-%m-%d %H:%i')

select DISTINCT aw.`staff_id`, aw.`staff_name`, aw.`staff_mobile`, aw.`staff_organization_id`, aw.`group_id` from `arrange_work` aw WHERE aw.`deleted` = 0
AND aw.`group_id` = #{param.groupId}
AND aw.`staff_organization_id` = #{param.organizationId}
AND aw.`month` = #{param.month}
AND aw.`staff_name` like CONCAT('%',#{param.staffName},'%')
order by aw.`staff_id`,aw.`staff_name`
